-- The only third-bank topology is frozen original -> approved old LSU -> final LSU.
CREATE OR REPLACE FUNCTION public.grammar_quiz_audit_chain(p_code TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.quiz_banks%ROWTYPE; m public.quiz_banks%ROWTYPE; n public.quiz_banks%ROWTYPE; total INTEGER;
BEGIN
  SELECT count(*) INTO total FROM (SELECT 1 FROM public.quiz_banks WHERE grammar_canonical_code=p_code LIMIT 4) bounded;
  IF total NOT IN (2,3) OR total=3 AND p_code<>'G-grammar-for-reading-long-sentence-untangling' THEN RETURN FALSE; END IF;
  SELECT * INTO r FROM public.quiz_banks WHERE code=p_code AND grammar_canonical_code=p_code AND grammar_predecessor_bank_id IS NULL;
  SELECT * INTO n FROM public.quiz_banks WHERE grammar_canonical_code=p_code AND grammar_is_current;
  IF r.id IS NULL OR n.id IS NULL OR r.grammar_is_current OR r.grammar_retired_at IS NULL OR n.grammar_retired_at IS NOT NULL
      OR r.topic_id IS DISTINCT FROM n.topic_id OR NOT r.is_published OR NOT n.is_published THEN RETURN FALSE; END IF;
  IF total=2 THEN RETURN n.grammar_predecessor_bank_id=r.id AND n.version=r.version+1
    AND (p_code='G-error-clinic-dangling-modifiers' AND n.code IN ('G-error-clinic-dangling-modifiers~8606094f523bdd1a') OR p_code='G-foundations-phrase-vs-clause' AND n.code IN ('G-foundations-phrase-vs-clause~66dfacf3a82258a9') OR p_code='G-grammar-for-reading-long-sentence-untangling' AND n.code IN ('G-grammar-for-reading-long-sentence-untangling~f272f1d183cb7667','G-grammar-for-reading-long-sentence-untangling~436d207e7bee05ab') OR p_code='G-grammar-for-reading-participle-clauses' AND n.code IN ('G-grammar-for-reading-participle-clauses~f63edb03e73d2e65') OR p_code='G-grammar-for-reading-reduced-relative-clauses' AND n.code IN ('G-grammar-for-reading-reduced-relative-clauses~f9c0cab2ce429253') OR p_code='G-parts-of-speech-verbs' AND n.code IN ('G-parts-of-speech-verbs~36e8b94fa47dfb8f') OR p_code='G-sentence-structures-passive-voice' AND n.code IN ('G-sentence-structures-passive-voice~2299da1f37da6ab3') OR p_code='G-tenses-past-continuous' AND n.code IN ('G-tenses-past-continuous~1d75f48d70c9e476') OR p_code='G-tenses-past-perfect' AND n.code IN ('G-tenses-past-perfect~297a5ae369e3bc72') OR p_code='G-tenses-present-continuous' AND n.code IN ('G-tenses-present-continuous~711e42becddee32b') OR p_code='G-tenses-present-perfect-continuous' AND n.code IN ('G-tenses-present-perfect-continuous~67ffbc97e73fdb1d') OR p_code='G-tenses-present-simple' AND n.code IN ('G-tenses-present-simple~97d6af8d735ff80c') OR p_code='G-error-clinic-affect-vs-effect' AND n.code IN ('G-error-clinic-affect-vs-effect~c87d4fdd24ddea27') OR p_code='G-error-clinic-article-errors' AND n.code IN ('G-error-clinic-article-errors~ad23d089ac41be88') OR p_code='G-error-clinic-do-vs-make' AND n.code IN ('G-error-clinic-do-vs-make~d3bad9f382acd708') OR p_code='G-error-clinic-double-subject-errors' AND n.code IN ('G-error-clinic-double-subject-errors~6e31b44046023040') OR p_code='G-error-clinic-economic-vs-economical' AND n.code IN ('G-error-clinic-economic-vs-economical~d5ef23a64adb05c7') OR p_code='G-error-clinic-historic-vs-historical' AND n.code IN ('G-error-clinic-historic-vs-historical~e37a2aa249f48e4d') OR p_code='G-error-clinic-overusing-i-think' AND n.code IN ('G-error-clinic-overusing-i-think~729c6ea364a059b1') OR p_code='G-error-clinic-preposition-errors' AND n.code IN ('G-error-clinic-preposition-errors~bb15a6eea5d32ac5') OR p_code='G-error-clinic-run-on-sentences' AND n.code IN ('G-error-clinic-run-on-sentences~b13dc26591c4b0a9') OR p_code='G-error-clinic-say-tell-speak-talk' AND n.code IN ('G-error-clinic-say-tell-speak-talk~0137d9256446cb89') OR p_code='G-error-clinic-sentence-fragments' AND n.code IN ('G-error-clinic-sentence-fragments~cc149ba1de3b9af3') OR p_code='G-error-clinic-subject-verb-agreement' AND n.code IN ('G-error-clinic-subject-verb-agreement~d6a17aea3de6b71e') OR p_code='G-error-clinic-tense-consistency' AND n.code IN ('G-error-clinic-tense-consistency~9b6e57bb43b9ebe6') OR p_code='G-error-clinic-wrong-pronoun-reference' AND n.code IN ('G-error-clinic-wrong-pronoun-reference~1b07c73439006faa') OR p_code='G-foundations-articles-a-an-sound-rules' AND n.code IN ('G-foundations-articles-a-an-sound-rules~5cbbc221550a722e') OR p_code='G-foundations-countable-vs-uncountable' AND n.code IN ('G-foundations-countable-vs-uncountable~96999469be5dd4e2') OR p_code='G-foundations-few-a-few-little-a-little' AND n.code IN ('G-foundations-few-a-few-little-a-little~f758a20763833a2a') OR p_code='G-foundations-noun-phrase-basics' AND n.code IN ('G-foundations-noun-phrase-basics~74d7cb25cb8a26c7') OR p_code='G-foundations-parts-of-speech' AND n.code IN ('G-foundations-parts-of-speech~035e374045b88f92') OR p_code='G-foundations-singular-vs-plural' AND n.code IN ('G-foundations-singular-vs-plural~01cc637857209ce2') OR p_code='G-foundations-this-that-these-those-in-use' AND n.code IN ('G-foundations-this-that-these-those-in-use~57c8cad7292c5c33') OR p_code='G-foundations-word-order' AND n.code IN ('G-foundations-word-order~e614a6cb55122036') OR p_code='G-fou